 33	    private static List<Integer> collectMatches(SearchState searchState) {
 34	        List<Integer> matches = new ArrayList<>(searchState.windowCount());
 35	        while (searchState.hasCurrentWindow()) {
 36	            if (searchState.isMatch()) {
 37	                matches.add(searchState.currentStart());
 38	            }
 39	            searchState.advance();
 40	        }
 41	        return matches;
 42	    }
