167	    private static final class RollingHash {
168	        private RollingHash() {
169	        }
170	
171	        private static int compute(String value, int length) {
172	            int hash = 0;
173	            for (int i = 0; i < length; i++) {
174	                hash = (RADIX * hash + value.charAt(i)) % MODULUS;
175	            }
176	            return hash;
177	        }
178	
179	        private static int roll(
180	            int currentHash,
181	            char outgoingChar,
182	            char incomingChar,
183	            int highOrderMultiplier
184	        ) {
185	            int nextHash = (
186	                RADIX * (currentHash - outgoingChar * highOrderMultiplier) + incomingChar
187	            ) % MODULUS;
188	
189	            if (nextHash < 0) {
190	                nextHash += MODULUS;
191	            }
192	
193	            return nextHash;
194	        }
195	    }
