198	        int highOrderMultiplier = 1;
199	        for (int i = 0; i < patternLength - 1; i++) {
200	            highOrderMultiplier = (highOrderMultiplier * RADIX) % MODULUS;
201	        }
202	        return highOrderMultiplier;
203	    }
